// Open the storage manager: every place you own that holds goods, and whose they are.
const api = game.modules.get("acks-extras")?.api?.location ?? globalThis.acksExtras?.location;
if (!api) return ui.notifications.error("ACKS Extras is not active.");
if (typeof api.openStorageManager !== "function") return ui.notifications.warn("ACKS Extras | Open Storage Manager needs a newer build of this module.");
api.openStorageManager();
